    "code": "// 🌐 گۆی ٣D — ٣٠٠ نوختە بە شێوەی گۆیەک دەسووڕێن: ئەوانەی نزیکترن گەورەتر و ڕووناکترن (قووڵایی). ماوس = گۆڕینی ئاڕاستە\nقەبارە(٣٦٠، ٣٦٠)\nنەگۆڕ نوختەکان = []\nبۆ i لە ٠ تا ٣٠٠ {\n  نەگۆڕ y = ١ - (i / ١٥٠)           // لە ١ بۆ -١\n  نەگۆڕ r = ڕەگ(گەورەترین(٠، ١ - y * y))\n  نەگۆڕ گ = i * ٢٫٣٩٩٩٦٣           // گۆشەی زێڕین\n  نوختەکان.زیادبکە({ x: کۆسینۆس(گ) * r، y: y، z: سینۆس(گ) * r })\n}\nگۆڕاو کات = ٠\nیاریبکە(() => {\n  کات += ٠٫٠٢\n  نەگۆڕ لار = ماوسY() >= ٠ ? (ماوسY() - ١٨٠) / ٣٠٠ : ٠٫٣\n  پاشبنەمابکە(ڕەنگی(٨، ١٠، ٢٥))\n  نەگۆڕ پرۆجەکت = نوختەکان.نەخشە(ن => {\n    نەگۆڕ x١ = ن.x * کۆسینۆس(کات) + ن.z * سینۆس(کات)\n    نەگۆڕ z١ = -ن.x * سینۆس(کات) + ن.z * کۆسینۆس(کات)\n    نەگۆڕ y٢ = ن.y * کۆسینۆس(لار) - z١ * سینۆس(لار)\n    نەگۆڕ z٢ = ن.y * سینۆس(لار) + z١ * کۆسینۆس(لار)\n    گەڕێنەوە { x: ١٨٠ + x١ * ١٣٠، y: ١٨٠ + y٢ * ١٣٠، z: z٢ }\n  })\n  پرۆجەکت.ڕیزبکە((a، b) => b.z - a.z)\n  بۆ هەر ن لە پرۆجەکت {\n    نەگۆڕ گەشی = (٠٫٥ - ن.z * ٠٫٥)\n    ڕەنگبکە(ڕەنگی(٨٠ + ١٦٠ * گەشی، ١٥٠ + ١٠٠ * گەشی، ٢٥٥، ٠٫٣ + ٠٫٧ * گەشی))\n    بازنە(ن.x، ن.y، ١٫٥ + ٢٫٥ * گەشی)\n  }\n})\n"
