    "code": "// یاری: فڵاپی — بۆشایی یان کلیک بۆ باڵ لێدان، لە بۆڕییەکان تێپەڕە\nقەبارە(٤٠٠، ٥٠٠)\nگۆڕاو y = ٢٥٠\nگۆڕاو خێرایی = ٠\nگۆڕاو بۆڕییەکان = [{ x: ٤٠٠، بۆشایی: ٢٠٠ }]\nگۆڕاو خاڵ = ٠\nگۆڕاو مردووە = هەڵە\nگۆڕاو کات = ٠\nگۆڕاو بەرزترین = ٠\n\nکار دووبارە() {\n  y = ٢٥٠\n  خێرایی = ٠\n  بۆڕییەکان = [{ x: ٤٠٠، بۆشایی: ٢٠٠ }]\n  خاڵ = ٠\n  مردووە = هەڵە\n}\n\nیاریبکە(() => {\n  کات += ١\n  گۆڕاو باڵ = کلیل(\"بۆشایی\") یان کلیل(\"سەرەوە\") یان ماوسگیراوە()\n  ئەگەر باڵ و نەک مردووە { خێرایی = -٦ }\n  ئەگەر کلیککراوە() و مردووە { دووبارە() }\n\n  ئەگەر نەک مردووە {\n    خێرایی += ٠٫٤\n    y += خێرایی\n    بۆ هەر ب لە بۆڕییەکان { ب.x -= ٣ }\n    ئەگەر بۆڕییەکان[بۆڕییەکان.درێژی - ١].x < ٢١٠ {\n      بۆڕییەکان.زیادبکە({ x: ٤٢٠، بۆشایی: هەڕەمەکی(١٢٠، ٣٨٠) })\n    }\n    ئەگەر بۆڕییەکان[٠].x < -٧٠ {\n      بۆڕییەکان.یەکەمیلابەرە()\n      خاڵ += ١\n      بەرزترین = گەورەترین(بەرزترین، خاڵ)\n    }\n    بۆ هەر ب لە بۆڕییەکان {\n      ئەگەر ٦٠ > ب.x - ١٥ و ٦٠ < ب.x + ٧٠ {\n        ئەگەر y < ب.بۆشایی - ٧٠ یان y > ب.بۆشایی + ٧٠ { مردووە = ڕاست }\n      }\n    }\n    ئەگەر y > ٤٨٠ یان y < ٠ { مردووە = ڕاست }\n  }\n\n  // ئاسمان\n  پاشبنەمابکە(\"ئاسمانی\")\n  ڕەنگبکە(ڕەنگی(٢٥٥، ٢٥٥، ٢٥٥، ٠٫٨))\n  بازنە(((کات * ٠٫٥) % ٥٠٠) - ٥٠، ٨٠، ٣٠)\n  بازنە(((کات * ٠٫٥) % ٥٠٠) - ١٨، ٨٨، ٢٤)\n  بازنە(((کات * ٠٫٥) % ٥٠٠) - ٧٨، ٨٨، ٢٢)\n\n  // بۆڕییەکان\n  بۆ هەر ب لە بۆڕییەکان {\n    ڕەنگبکە(\"سەوز\")\n    لاکێش(ب.x، ٠، ٧٠، ب.بۆشایی - ٧٠)\n    لاکێش(ب.x، ب.بۆشایی + ٧٠، ٧٠، ٥٠٠)\n    ڕەنگبکە(ڕەنگی(٠، ١٢٠، ٠))\n    لاکێش(ب.x - ٥، ب.بۆشایی - ٩٠، ٨٠، ٢٠)\n    لاکێش(ب.x - ٥، ب.بۆشایی + ٧٠، ٨٠، ٢٠)\n  }\n\n  // باڵندە\n  ڕەنگبکە(\"زەرد\")\n  بازنە(٦٠، y، ١٨)\n  ڕەنگبکە(\"سپی\")\n  بازنە(٦٨، y - ٥، ٦)\n  ڕەنگبکە(\"ڕەش\")\n  بازنە(٧٠، y - ٥، ٣)\n  ڕەنگبکە(\"نارنجی\")\n  سێگۆشە(٧٨، y، ٩٢، y + ٤، ٧٨، y + ٨)\n\n  ڕەنگبکە(\"سپی\")\n  نووسین(خاڵ، ١٨٠، ٦٠، ٤٨)\n  نووسین(\"باشترین: \" + بەرزترین، ١٠، ٢٥، ١٨)\n  ئەگەر مردووە {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٦))\n    لاکێش(٠، ٠، ٤٠٠، ٥٠٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(\"کۆتایی!\", ١٤٠، ٢٣٠، ٤٠)\n    نووسین(\"کلیک بکە بۆ دووبارە\", ١١٠، ٢٨٠، ٢٢)\n  }\n})\n"
