    "code": "// 🕒 کاتژمێری زیندوو — بە ئێستا() کاتی ڕاستەقینە دەخوێنێتەوە\nقەبارە(٤٠٠، ٤٠٠)\nنەگۆڕ ن = ٢٠٠\n\nکار دەست(درێژی، ئەستووری، گۆشە، ڕەنگ) {\n  هێڵڕەنگبکە(ڕەنگ)\n  ئەستووریبکە(ئەستووری)\n  نەگۆڕ ڕادیان = (گۆشە - ٩٠) * پای / ١٨٠\n  هێڵ(ن، ن، ن + کۆسینۆس(ڕادیان) * درێژی، ن + سینۆس(ڕادیان) * درێژی)\n}\n\nیاریبکە(() => {\n  نەگۆڕ ک = ئێستا()\n  پاشبنەمابکە(ڕەنگی(١٢، ١٨، ٣٢))\n\n  ڕەنگبکە(ڕەنگی(٢٤، ٣٤، ٥٨))\n  بازنە(ن، ن، ١٨٠)\n  ڕەنگبکە(ڕەنگی(١٢، ١٨، ٣٢))\n  بازنە(ن، ن، ١٧٠)\n\n  بۆ i لە ٠ تا ٥٩ {\n    نەگۆڕ ڕ = (i * ٦ - ٩٠) * پای / ١٨٠\n    نەگۆڕ درێژ = i % ٥ == ٠ ? ١٨ : ٧\n    هێڵڕەنگبکە(i % ٥ == ٠ ? \"زەرد\" : \"خۆڵەمێشی\")\n    ئەستووریبکە(i % ٥ == ٠ ? ٣ : ١)\n    هێڵ(ن + کۆسینۆس(ڕ) * ١٦٥، ن + سینۆس(ڕ) * ١٦٥، ن + کۆسینۆس(ڕ) * (١٦٥ - درێژ)، ن + سینۆس(ڕ) * (١٦٥ - درێژ))\n  }\n\n  دەست(٩٥، ٩، (ک.سەعات % ١٢ + ک.خولەک / ٦٠) * ٣٠، \"سپی\")\n  دەست(١٣٥، ٦، (ک.خولەک + ک.چرکە / ٦٠) * ٦، \"سپی\")\n  دەست(١٥٠، ٢، ک.چرکە * ٦، \"سوور\")\n  ڕەنگبکە(\"سوور\")\n  بازنە(ن، ن، ٩)\n  ڕەنگبکە(\"سپی\")\n  نووسین(ک.سەعات + \":\" + (ک.خولەک < ١٠ ? \"٠\" : \"\") + ک.خولەک، ١٧٠، ٢٨٠، ٢٢)\n})\n"
