    "code": "// 🪐 سیستەمی خۆر — هەسارەکان بە دەوری خۆردا دەسووڕێنەوە\nقەبارە(٥٠٠، ٥٠٠)\nگۆڕاو کات = ٠\n\nنەگۆڕ هەسارەکان = [\n  { دووری: ٥٠، قەبارە: ٦، خێرایی: ٣، ڕەنگ: \"خۆڵەمێشی\" },\n  { دووری: ٨٠، قەبارە: ١٠، خێرایی: ٢، ڕەنگ: \"نارنجی\" },\n  { دووری: ١١٥، قەبارە: ١١، خێرایی: ١٫٥، ڕەنگ: \"شین\" },\n  { دووری: ١٥٠، قەبارە: ٩، خێرایی: ١٫٢، ڕەنگ: \"سوور\" },\n  { دووری: ١٩٥، قەبارە: ٢٠، خێرایی: ٠٫٧، ڕەنگ: \"قاوەیی\" },\n  { دووری: ٢٣٥، قەبارە: ١٦، خێرایی: ٠٫٥، ڕەنگ: \"زەرد\" },\n]\n\nنەگۆڕ ئەستێرەکان = []\nبۆ i لە ١ تا ٩٠ { ئەستێرەکان.زیادبکە({ x: هەڕەمەکی(٠، ٥٠٠)، y: هەڕەمەکی(٠، ٥٠٠)، r: هەڕەمەکی(١، ٢) }) }\n\nیاریبکە(() => {\n  کات += ٠٫٦\n  پاشبنەمابکە(ڕەنگی(٥، ٥، ١٥))\n  ڕەنگبکە(\"سپی\")\n  بۆ هەر ئ لە ئەستێرەکان { بازنە(ئ.x، ئ.y، ئ.r) }\n\n  بۆ هەر ه لە هەسارەکان {\n    هێڵڕەنگبکە(ڕەنگی(٨٠، ٨٠، ١٢٠، ٠٫٤))\n    ئەستووریبکە(١)\n    بازنەهێڵ(٢٥٠، ٢٥٠، ه.دووری)\n  }\n  خۆر(٢٥٠، ٢٥٠، ٢٨)\n  بۆ هەر ه لە هەسارەکان {\n    نەگۆڕ گ = کات * ه.خێرایی * پای / ١٨٠\n    ڕەنگبکە(ه.ڕەنگ)\n    بازنە(٢٥٠ + کۆسینۆس(گ) * ه.دووری، ٢٥٠ + سینۆس(گ) * ه.دووری، ه.قەبارە)\n  }\n})\n"
