    "thumb": 150,
    "code": "// یاری: تەقاندن — کەشتییەکەت بە ← → بجووڵێنە و بە بۆشایی گوللە بەرە؛ دوژمنەکان بتەقێنە\nقەبارە(٤٠٠، ٥٠٠)\nگۆڕاو کەشتی = ١٨٠\nگۆڕاو گوللەکان = []\nگۆڕاو دوژمنەکان = []\nگۆڕاو خاڵ = ٠\nگۆڕاو ژیان = ٣\nگۆڕاو کات = ٠\nگۆڕاو ئاگر = ٠\nنەگۆڕ ئەستێرەکان = []\nبۆ i لە ١ تا ٥٠ { ئەستێرەکان.زیادبکە({ x: هەڕەمەکی(٠، ٤٠٠)، y: هەڕەمەکی(٠، ٥٠٠)، خ: هەڕەمەکی(١، ٣) }) }\n\nکار دووبارە() {\n  گوللەکان = []\n  دوژمنەکان = []\n  خاڵ = ٠\n  ژیان = ٣\n}\n\nیاریبکە(() => {\n  کات += ١\n  ئاگر -= ١\n\n  ئەگەر ژیان > ٠ {\n    ئەگەر کلیل(\"چەپ\") { کەشتی -= ٦ }\n    ئەگەر کلیل(\"ڕاست\") { کەشتی += ٦ }\n    کەشتی = سنوور(کەشتی، ٠، ٣٦٠)\n\n    ئەگەر (کلیل(\"بۆشایی\") یان ماوسگیراوە()) و ئاگر <= ٠ {\n      گوللەکان.زیادبکە({ x: کەشتی + ٢٠، y: ٤٣٠ })\n      ئاگر = ١٠\n    }\n    ئەگەر کات % ٤٥ == ٠ {\n      دوژمنەکان.زیادبکە({ x: هەڕەمەکی(١٠، ٣٥٠)، y: -٣٠، خ: هەڕەمەکی(١، ٣) })\n    }\n\n    بۆ هەر گ لە گوللەکان { گ.y -= ٩ }\n    بۆ هەر د لە دوژمنەکان { د.y += د.خ }\n\n    // پێکدان\n    بۆ هەر د لە دوژمنەکان {\n      بۆ هەر گ لە گوللەکان {\n        ئەگەر دووری(گ.x، گ.y، د.x + ١٥، د.y + ١٥) < ٢٢ {\n          د.مردووە = ڕاست\n          گ.مردووە = ڕاست\n          خاڵ += ١\n        }\n      }\n      ئەگەر د.y > ٥٠٠ { د.مردووە = ڕاست؛ ژیان -= ١ }\n    }\n    گوللەکان = گوللەکان.پاڵاوتن(گ => نەک گ.مردووە و گ.y > -١٠)\n    دوژمنەکان = دوژمنەکان.پاڵاوتن(د => نەک د.مردووە)\n  }\n\n  پاشبنەمابکە(ڕەنگی(٥، ٥، ٢٠))\n  ڕەنگبکە(\"سپی\")\n  بۆ هەر ئ لە ئەستێرەکان {\n    ئ.y = (ئ.y + ئ.خ * ٠٫٥) % ٥٠٠\n    بازنە(ئ.x، ئ.y، ١٫٥)\n  }\n  ڕەنگبکە(\"زەرد\")\n  بۆ هەر گ لە گوللەکان { لاکێش(گ.x - ٢، گ.y، ٤، ١٢) }\n  بۆ هەر د لە دوژمنەکان {\n    ڕەنگبکە(\"سوور\")\n    سێگۆشە(د.x، د.y، د.x + ٣٠، د.y، د.x + ١٥، د.y + ٣٠)\n    ڕەنگبکە(\"سپی\")\n    بازنە(د.x + ١٥، د.y + ٨، ٣)\n  }\n  ڕەنگبکە(\"ئاسمانی\")\n  سێگۆشە(کەشتی، ٤٦٠، کەشتی + ٤٠، ٤٦٠، کەشتی + ٢٠، ٤٣٠)\n  ڕەنگبکە(\"نارنجی\")\n  سێگۆشە(کەشتی + ١٥، ٤٦٠، کەشتی + ٢٥، ٤٦٠، کەشتی + ٢٠، ٤٦٠ + ٦ + (کات % ٤) * ٢)\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"خاڵ: \" + خاڵ، ١٠، ٢٨، ٢٠)\n  نووسین(\"❤ \" + گەورەترین(ژیان، ٠)، ٣٤٠، ٢٨، ٢٠)\n\n  ئەگەر ژیان <= ٠ {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٧))\n    لاکێش(٠، ٠، ٤٠٠، ٥٠٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(\"کۆتایی! خاڵ: \" + خاڵ، ٩٠، ٢٣٠، ٣٠)\n    نووسین(\"کلیک بکە بۆ دووبارە\", ٩٥، ٢٧٠، ٢٠)\n    ئەگەر کلیککراوە() { دووبارە() }\n  }\n})\n"
