    "thumb": 40,
    "code": "// یاری: مشک بکوژە — هەر مشکێک کە دەرکەوت کلیکی لێ بکە پێش ئەوەی ون بێت!\nقەبارە(٤٠٠، ٣٢٠)\nگۆڕاو خاڵ = ٠\nگۆڕاو کات = ٣٠ * ٦٠\nگۆڕاو کون = -١\nگۆڕاو ماوە = ٠\nگۆڕاو لێدان = ٠\n\nکار شوێن(i) {\n  گەڕێنەوە { x: ٧٠ + (i % ٣) * ١٣٠، y: ١٣٠ + خوارکە(i / ٣) * ٩٠ }\n}\n\nیاریبکە(() => {\n  ئەگەر کات > ٠ {\n    کات -= ١\n    ماوە -= ١\n    ئەگەر ماوە <= ٠ { کون = هەڕەمەکی(٠، ٥)؛ ماوە = هەڕەمەکی(٣٠، ٦٠) }\n    ئەگەر کلیککراوە() {\n      گۆڕاو ش = شوێن(کون)\n      ئەگەر کون >= ٠ و دووری(ماوسX()، ماوسY()، ش.x، ش.y) < ٣٨ {\n        خاڵ += ١\n        لێدان = ١٠\n        کون = -١\n        ماوە = ٢٥\n      }\n    }\n  }\n  لێدان -= ١\n\n  پاشبنەمابکە(ڕەنگی(٤٠، ١٢٠، ٥٠))\n  بۆ i لە ٠ تا ٥ {\n    گۆڕاو ش = شوێن(i)\n    ڕەنگبکە(ڕەنگی(٦٠، ٤٠، ٢٠))\n    بازنە(ش.x، ش.y + ٥، ٤٢)\n    ڕەنگبکە(ڕەنگی(٢٠، ١٥، ١٠))\n    بازنە(ش.x، ش.y، ٣٨)\n    ئەگەر i == کون {\n      ڕەنگبکە(ڕەنگی(١٥٠، ١٠٠، ٦٠))\n      بازنە(ش.x، ش.y، ٣٠)\n      ڕەنگبکە(\"سپی\")\n      بازنە(ش.x - ١٠، ش.y - ٧، ٥)\n      بازنە(ش.x + ١٠، ش.y - ٧، ٥)\n      ڕەنگبکە(\"ڕەش\")\n      بازنە(ش.x - ١٠، ش.y - ٧، ٢)\n      بازنە(ش.x + ١٠، ش.y - ٧، ٢)\n      ڕەنگبکە(\"پەمەیی\")\n      بازنە(ش.x، ش.y + ٧، ٥)\n    }\n  }\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"خاڵ: \" + خاڵ، ١٥، ٣٥، ٢٦)\n  نووسین(\"کات: \" + خوارکە(کات / ٦٠)، ٢٨٠، ٣٥، ٢٦)\n  ئەگەر لێدان > ٠ { نووسین(\"✨ باشە!\", ١٦٠، ٨٠، ٢٤) }\n  ئەگەر کات <= ٠ {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٧))\n    لاکێش(٠، ٠، ٤٠٠، ٣٢٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(\"کاتەکە تەواو بوو! خاڵ: \" + خاڵ، ٨٠، ١٥٠، ٢٦)\n    نووسین(\"کلیک بکە بۆ دووبارە\", ١١٠، ١٩٠، ٢٠)\n    ئەگەر کلیککراوە() { خاڵ = ٠؛ کات = ١٨٠٠ }\n  }\n})\n"
