    "thumb": 5,
    "code": "// یاری: ئێکس-ئۆ — تۆ ✕ ی، کۆمپیوتەر ◯. کلیک بکە لە خانەیەکی بەتاڵ\nقەبارە(٣٠٠، ٣٦٠)\nگۆڕاو تەخت = [٠، ٠، ٠، ٠، ٠، ٠، ٠، ٠، ٠]    // ٠ = بەتاڵ، ١ = تۆ، ٢ = کۆمپیوتەر\nگۆڕاو نۆرەی = ١\nگۆڕاو چاوەڕێ = ٠\nگۆڕاو ئەنجام = ٠                             // ٠ = بەردەوام، ١/٢ = براوە، ٣ = یەکسان\n\nنەگۆڕ هێڵەکان = [[٠، ١، ٢]، [٣، ٤، ٥]، [٦، ٧، ٨]، [٠، ٣، ٦]، [١، ٤، ٧]، [٢، ٥، ٨]، [٠، ٤، ٨]، [٢، ٤، ٦]]\n\nکار براوە(ت) {\n  بۆ هەر ه لە هێڵەکان {\n    ئەگەر ت[ه[٠]] != ٠ و ت[ه[٠]] == ت[ه[١]] و ت[ه[٠]] == ت[ه[٢]] { گەڕێنەوە ت[ه[٠]] }\n  }\n  ئەگەر نەک ت.لەخۆدەگرێت(٠) { گەڕێنەوە ٣ }\n  گەڕێنەوە ٠\n}\n\n// کۆمپیوتەر: یەکەم ببەرەوە، پاشان دژەکەت بوەستێنە، پاشان ناوەند، پاشان هەر شوێنێک\nکار بڕیاری_کۆمپیوتەر() {\n  بۆ هەر کێ لە [٢، ١] {\n    بۆ i لە ٠ تا ٨ {\n      ئەگەر تەخت[i] == ٠ {\n        تەخت[i] = کێ\n        نەگۆڕ ب = براوە(تەخت) == کێ\n        تەخت[i] = ٠\n        ئەگەر ب { گەڕێنەوە i }\n      }\n    }\n  }\n  ئەگەر تەخت[٤] == ٠ { گەڕێنەوە ٤ }\n  نەگۆڕ بەتاڵ = []\n  بۆ i لە ٠ تا ٨ { ئەگەر تەخت[i] == ٠ { بەتاڵ.زیادبکە(i) } }\n  گەڕێنەوە بەتاڵ[هەڕەمەکی(٠، بەتاڵ.درێژی - ١)]\n}\n\nیاریبکە(() => {\n  ئەگەر ئەنجام == ٠ {\n    ئەگەر نۆرەی == ١ {\n      ئەگەر کلیککراوە() و ماوسY() < ٣٠٠ {\n        نەگۆڕ خانە = خوارکە(ماوسX() / ١٠٠) + خوارکە(ماوسY() / ١٠٠) * ٣\n        ئەگەر تەخت[خانە] == ٠ { تەخت[خانە] = ١؛ نۆرەی = ٢؛ چاوەڕێ = ٣٠ }\n      }\n    } ئەگەرنا {\n      چاوەڕێ -= ١\n      ئەگەر چاوەڕێ <= ٠ { تەخت[بڕیاری_کۆمپیوتەر()] = ٢؛ نۆرەی = ١ }\n    }\n    ئەنجام = براوە(تەخت)\n  } ئەگەرنا ئەگەر کلیککراوە() {\n    تەخت = [٠، ٠، ٠، ٠، ٠، ٠، ٠، ٠، ٠]\n    ئەنجام = ٠\n    نۆرەی = ١\n  }\n\n  پاشبنەمابکە(ڕەنگی(١٥، ٢٠، ٤٠))\n  هێڵڕەنگبکە(ڕەنگی(٨٠، ٩٠، ١٣٠))\n  ئەستووریبکە(٤)\n  هێڵ(١٠٠، ١٠، ١٠٠، ٢٩٠)؛ هێڵ(٢٠٠، ١٠، ٢٠٠، ٢٩٠)\n  هێڵ(١٠، ١٠٠، ٢٩٠، ١٠٠)؛ هێڵ(١٠، ٢٠٠، ٢٩٠، ٢٠٠)\n  بۆ i لە ٠ تا ٨ {\n    نەگۆڕ cx = (i % ٣) * ١٠٠ + ٥٠\n    نەگۆڕ cy = خوارکە(i / ٣) * ١٠٠ + ٥٠\n    ئەستووریبکە(٩)\n    ئەگەر تەخت[i] == ١ {\n      هێڵڕەنگبکە(\"ئاسمانی\")\n      هێڵ(cx - ٢٨، cy - ٢٨، cx + ٢٨، cy + ٢٨)؛ هێڵ(cx + ٢٨، cy - ٢٨، cx - ٢٨، cy + ٢٨)\n    } ئەگەرنا ئەگەر تەخت[i] == ٢ {\n      هێڵڕەنگبکە(\"نارنجی\")\n      بازنەهێڵ(cx، cy، ٣٠)\n    }\n  }\n  ڕەنگبکە(\"سپی\")\n  گۆڕاو پەیام = \"نۆرەی تۆیە — کلیک بکە\"\n  ئەگەر نۆرەی == ٢ { پەیام = \"کۆمپیوتەر بیر دەکاتەوە...\" }\n  ئەگەر ئەنجام == ١ { پەیام = \"بردتەوە! 🎉 (کلیک = دووبارە)\" }\n  ئەگەر ئەنجام == ٢ { پەیام = \"کۆمپیوتەر بردیەوە (کلیک = دووبارە)\" }\n  ئەگەر ئەنجام == ٣ { پەیام = \"یەکسان بوون (کلیک = دووبارە)\" }\n  نووسین(پەیام، ٤٠، ٣٣٥، ٢٠)\n})\n"
