    "code": "// یاری: چوار بە دووی یەک 🔴🟡 — کلیک لە ستوونێک بکە، چوار بەردی هاوڕەنگ لە ڕیزێکدا (ئاسۆیی، ستوونی، لار) ببە\nقەبارە(٣٥٠، ٤٢٠)\nگۆڕاو تەخت = []\nگۆڕاو کێ = ١          // ١ تۆ، ٢ کۆمپیوتەر\nگۆڕاو براوە = ٠       // ٠ بەردەوام، ١/٢ براوە، ٣ یەکسان\nگۆڕاو چاوەڕێ = ٠\n\nکار دەستپێکردن() {\n  تەخت = []\n  بۆ i لە ١ تا ٤٢ { تەخت.زیادبکە(٠) }\n  کێ = ١؛ براوە = ٠\n}\nدەستپێکردن()\n\nکار خانە(ڕ، ک) { گەڕێنەوە ڕ >= ٠ و ڕ < ٦ و ک >= ٠ و ک < ٧ ? تەخت[ڕ * ٧ + ک] : -١ }\n\nکار ڕیزی_چوار(کەس) {\n  بۆ ڕ لە ٠ تا ٥ {\n    بۆ ک لە ٠ تا ٦ {\n      بۆ هەر د لە [[٠، ١]، [١، ٠]، [١، ١]، [١، -١]] {\n        گۆڕاو ژمارە = ٠\n        بۆ i لە ٠ تا ٣ { ئەگەر خانە(ڕ + د[٠] * i، ک + د[١] * i) == کەس { ژمارە += ١ } }\n        ئەگەر ژمارە == ٤ { گەڕێنەوە ڕاست }\n      }\n    }\n  }\n  گەڕێنەوە هەڵە\n}\n\nکار بیخە(ک، کەس) {\n  بۆ ڕ لە ٥ تا ٠ هەنگاو -١ {\n    ئەگەر تەخت[ڕ * ٧ + ک] == ٠ { تەخت[ڕ * ٧ + ک] = کەس؛ گەڕێنەوە ڕاست }\n  }\n  گەڕێنەوە هەڵە\n}\n\nکار کاتی_کۆمپیوتەر() {\n  // ١. ببە ٢. دژەکەت بوەستێنە ٣. ناوەندی نزیک\n  بۆ هەر کەس لە [٢، ١] {\n    بۆ ک لە ٠ تا ٦ {\n      ئەگەر تەخت[ک] == ٠ {\n        بیخە(ک، کەس)\n        نەگۆڕ ب = ڕیزی_چوار(کەس)\n        بۆ ڕ لە ٠ تا ٥ { ئەگەر تەخت[ڕ * ٧ + ک] == کەس { تەخت[ڕ * ٧ + ک] = ٠؛ ڕ = ٧ } }\n        ئەگەر ب { گەڕێنەوە ک }\n      }\n    }\n  }\n  نەگۆڕ ڕیزبەندی = [٣، ٢، ٤، ١، ٥، ٠، ٦]\n  بۆ هەر ک لە ڕیزبەندی { ئەگەر تەخت[ک] == ٠ { گەڕێنەوە ک } }\n  گەڕێنەوە -١\n}\n\nیاریبکە(() => {\n  ئەگەر براوە == ٠ {\n    ئەگەر کێ == ١ {\n      ئەگەر کلیککراوە() {\n        نەگۆڕ ک = خوارکە(ماوسX() / ٥٠)\n        ئەگەر ک >= ٠ و ک < ٧ و بیخە(ک، ١) {\n          ئەگەر ڕیزی_چوار(١) { براوە = ١ } ئەگەرنا ئەگەر نەک تەخت.لەخۆدەگرێت(٠) { براوە = ٣ } ئەگەرنا { کێ = ٢؛ چاوەڕێ = ٣٠ }\n        }\n      }\n    } ئەگەرنا {\n      چاوەڕێ -= ١\n      ئەگەر چاوەڕێ <= ٠ {\n        نەگۆڕ ک = کاتی_کۆمپیوتەر()\n        ئەگەر ک >= ٠ { بیخە(ک، ٢) }\n        ئەگەر ڕیزی_چوار(٢) { براوە = ٢ } ئەگەرنا ئەگەر نەک تەخت.لەخۆدەگرێت(٠) { براوە = ٣ } ئەگەرنا { کێ = ١ }\n      }\n    }\n  } ئەگەرنا ئەگەر کلیککراوە() { دەستپێکردن() }\n\n  پاشبنەمابکە(ڕەنگی(١٥، ٢٠، ٤٥))\n  ڕەنگبکە(ڕەنگی(٣٠، ٦٠، ١٨٠))\n  لاکێش(٠، ٥٠، ٣٥٠، ٣٠٠)\n  بۆ ڕ لە ٠ تا ٥ {\n    بۆ ک لە ٠ تا ٦ {\n      نەگۆڕ v = تەخت[ڕ * ٧ + ک]\n      ڕەنگبکە(v == ١ ? \"سوور\" : v == ٢ ? \"زەرد\" : ڕەنگی(١٥، ٢٠، ٤٥))\n      بازنە(ک * ٥٠ + ٢٥، ڕ * ٥٠ + ٧٥، ٢٠)\n    }\n  }\n  ڕەنگبکە(\"سپی\")\n  گۆڕاو پەیام = کێ == ١ ? \"نۆرەی تۆیە: ستوونێک هەڵبژێرە\" : \"کۆمپیوتەر بیر دەکاتەوە...\"\n  ئەگەر براوە == ١ { پەیام = \"بردتەوە! 🎉 (کلیک = دووبارە)\" }\n  ئەگەر براوە == ٢ { پەیام = \"کۆمپیوتەر بردیەوە (کلیک = دووبارە)\" }\n  ئەگەر براوە == ٣ { پەیام = \"یەکسان بوون (کلیک = دووبارە)\" }\n  نووسین(پەیام، ٢٠، ٣٥، ٢٠)\n  ئەگەر ماوسY() >= ٠ و براوە == ٠ و کێ == ١ {\n    ڕەنگبکە(ڕەنگی(٢٥٥، ٢٥٥، ٢٥٥، ٠٫٢))\n    لاکێش(خوارکە(ماوسX() / ٥٠) * ٥٠، ٥٠، ٥٠، ٣٠٠)\n  }\n})\n"
