    "code": "// یاری: چرا بکوژێنەوە 💡 — هەر کلیکێک خانەکە و ٤ دراوسێکەی دەگۆڕێت (ڕووناک ↔ تاریک). هەموو چراکان بکوژێنەوە!\nقەبارە(٣٥٠، ٤٢٠)\nنەگۆڕ مەتر = ٥\nگۆڕاو چراکان = []\nگۆڕاو جووڵە = ٠\nگۆڕاو بردرا = هەڵە\n\nکار گۆڕین(x، y) {\n  بۆ هەر د لە [[٠، ٠]، [١، ٠]، [-١، ٠]، [٠، ١]، [٠، -١]] {\n    نەگۆڕ nx = x + د[٠]\n    نەگۆڕ ny = y + د[١]\n    ئەگەر nx >= ٠ و nx < مەتر و ny >= ٠ و ny < مەتر { چراکان[ny * مەتر + nx] = نەک چراکان[ny * مەتر + nx] }\n  }\n}\n\nکار دەستپێکردن() {\n  چراکان = []\n  بۆ i لە ١ تا مەتر * مەتر { چراکان.زیادبکە(هەڵە) }\n  // دروستکردنی تەختە بە کلیکی هەڕەمەکی (هەمیشە چارەسەری هەیە)\n  بۆ i لە ١ تا ١٢ { گۆڕین(هەڕەمەکی(٠، ٤)، هەڕەمەکی(٠، ٤)) }\n  جووڵە = ٠؛ بردرا = هەڵە\n}\nدەستپێکردن()\n\nیاریبکە(() => {\n  ئەگەر کلیککراوە() {\n    ئەگەر بردرا { دەستپێکردن() } ئەگەرنا ئەگەر ماوسY() >= ٧٠ {\n      نەگۆڕ x = خوارکە(ماوسX() / ٧٠)\n      نەگۆڕ y = خوارکە((ماوسY() - ٧٠) / ٧٠)\n      ئەگەر x < مەتر و y < مەتر { گۆڕین(x، y)؛ جووڵە += ١ }\n      بردرا = نەک چراکان.لەخۆدەگرێت(ڕاست)\n    }\n  }\n  پاشبنەمابکە(ڕەنگی(٢٠، ٢٠، ٣٥))\n  بۆ y لە ٠ تا مەتر - ١ {\n    بۆ x لە ٠ تا مەتر - ١ {\n      نەگۆڕ ڕووناکە = چراکان[y * مەتر + x]\n      ڕەنگبکە(ڕووناکە ? ڕەنگی(٢٥٥، ٢٢٠، ٨٠) : ڕەنگی(٤٠، ٤٥، ٧٠))\n      لاکێش(x * ٧٠ + ٥، y * ٧٠ + ٧٥، ٦٠، ٦٠)\n      ئەگەر ڕووناکە { ڕەنگبکە(ڕەنگی(٢٥٥، ٢٥٥، ٢٠٠، ٠٫٦))؛ بازنە(x * ٧٠ + ٣٥، y * ٧٠ + ١٠٥، ١٥) }\n    }\n  }\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"جووڵە: \" + جووڵە، ١٥، ٤٠، ٢٤)\n  نووسین(بردرا ? \"🎉 هەموو کوژاونەتەوە! کلیک = دووبارە\" : \"چراکان بکوژێنەوە\", بردرا ? ٢٠ : ١٨٠، ٤٠، بردرا ? ١٥ : ١٨)\n})\n"
