    "code": "// یاری: تاوەری هانۆی 🗼 — هەموو ٤ قوپەکە لە تیرەی چەپەوە بگوازەرەوە بۆ تیرەی ڕاست. قوپی گەورە نابێت لەسەر بچووک بێت! (کەمترین: ١٥ جووڵە)\nقەبارە(٤٥٠، ٣٠٠)\nگۆڕاو تیرەکان = [[٤، ٣، ٢، ١]، []، []]    // هەر تیرەیەک ستاکێکە (لە خوارەوە بۆ سەرەوە)\nگۆڕاو هەڵبژێردراو = -١\nگۆڕاو جووڵە = ٠\nگۆڕاو پەیام = \"\"\nگۆڕاو پەیامکات = ٠\n\nکار دەستپێکردن() { تیرەکان = [[٤، ٣، ٢، ١]، []، []]؛ هەڵبژێردراو = -١؛ جووڵە = ٠ }\n\nیاریبکە(() => {\n  پەیامکات -= ١\n  ئەگەر کلیککراوە() {\n    نەگۆڕ ت = خوارکە(ماوسX() / ١٥٠)\n    ئەگەر تیرەکان[٢].درێژی == ٤ { دەستپێکردن() } ئەگەرنا ئەگەر ت >= ٠ و ت <= ٢ {\n      ئەگەر هەڵبژێردراو == -١ {\n        ئەگەر تیرەکان[ت].درێژی > ٠ { هەڵبژێردراو = ت }\n      } ئەگەرنا ئەگەر ت == هەڵبژێردراو { هەڵبژێردراو = -١ } ئەگەرنا {\n        نەگۆڕ لە = تیرەکان[هەڵبژێردراو]\n        نەگۆڕ بۆتیرە = تیرەکان[ت]\n        نەگۆڕ قوپ = لە[لە.درێژی - ١]\n        ئەگەر بۆتیرە.درێژی == ٠ یان بۆتیرە[بۆتیرە.درێژی - ١] > قوپ {\n          لە.لابەرە()؛ بۆتیرە.زیادبکە(قوپ)؛ جووڵە += ١\n        } ئەگەرنا { پەیام = \"قوپی گەورە نابێت لەسەر بچووک بێت!\"؛ پەیامکات = ٩٠ }\n        هەڵبژێردراو = -١\n      }\n    }\n  }\n  پاشبنەمابکە(ڕەنگی(٢٥، ٣٠، ٥٠))\n  بۆ i لە ٠ تا ٢ {\n    ڕەنگبکە(هەڵبژێردراو == i ? ڕەنگی(٥٠، ٦٠، ١٠٠) : ڕەنگی(٣٥، ٤٠، ٦٥))\n    لاکێش(i * ١٥٠ + ٥، ٤٠، ١٤٠، ٢٣٠)\n    ڕەنگبکە(ڕەنگی(١٨٠، ١٨٠، ١٩٠))\n    لاکێش(i * ١٥٠ + ٧١، ٦٠، ٨، ٢١٠)\n    لاکێش(i * ١٥٠ + ٢٠، ٢٦٨، ١١٠، ٦)\n    بۆ ک لە ٠ تا تیرەکان[i].درێژی - ١ {\n      نەگۆڕ قوپ = تیرەکان[i][ک]\n      ڕەنگبکە(پەلکەزێڕینە(قوپ * ٧٠))\n      لاکێش(i * ١٥٠ + ٧٥ - قوپ * ١٦، ٢٤٠ - ک * ٣٠، قوپ * ٣٢، ٢٦)\n    }\n  }\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"جووڵە: \" + جووڵە، ١٥، ٢٨، ٢٢)\n  ئەگەر پەیامکات > ٠ { ڕەنگبکە(\"سوور\")؛ نووسین(پەیام، ١٠٠، ٢٩٠، ١٨) }\n  ئەگەر تیرەکان[٢].درێژی == ٤ { ڕەنگبکە(\"سەوز\")؛ نووسین(\"🎉 تەواو بوو لە \" + جووڵە + \" جووڵە! کلیک = دووبارە\", ٣٠، ٢٩٠، ١٨) }\n})\n"
