    "thumb": 3,
    "code": "// یاری: گۆڵف ⛳ — ماوس لەسەر تۆپەکە دابگرە، دواوە بکێشە و بەریبدە. تۆپەکە بخەرە ناو کونە ڕەشەکە بە کەمترین لێدان! (٣ قۆناغ)\nقەبارە(٥٠٠، ٣٢٠)\nنەگۆڕ قۆناغەکان = [\n  { تۆپ: [٧٠، ١٦٠]، کون: [٤٢٠، ١٦٠]، ڕێگر: [] }،\n  { تۆپ: [٧٠، ٨٠]، کون: [٤٢٠، ٢٥٠]، ڕێگر: [[٢٣٠، ٥٠، ٢٠، ١٦٠]] }،\n  { تۆپ: [٧٠، ٢٦٠]، کون: [٤٢٠، ٧٠]، ڕێگر: [[١٨٠، ٠، ٢٠، ١٦٠]، [٣١٠، ١٨٠، ٢٠، ١٤٠]] }،\n]\nگۆڕاو قۆناغ = ٠\nگۆڕاو x = ٧٠\nگۆڕاو y = ١٦٠\nگۆڕاو vx = ٠\nگۆڕاو vy = ٠\nگۆڕاو کێشان = هەڵە\nگۆڕاو لێدان = ٠\nگۆڕاو کۆی = ٠\nگۆڕاو تەواو = هەڵە\n\nکار بارکردن(ق) {\n  x = قۆناغەکان[ق].تۆپ[٠]؛ y = قۆناغەکان[ق].تۆپ[١]؛ vx = ٠؛ vy = ٠؛ لێدان = ٠؛ تەواو = هەڵە\n}\nبارکردن(٠)\n\nیاریبکە(() => {\n  نەگۆڕ ق = قۆناغەکان[قۆناغ]\n  نەگۆڕ خێرایی = دووری(٠، ٠، vx، vy)\n  ئەگەر نەک تەواو {\n    ئەگەر خێرایی < ٠٫٢ {\n      vx = ٠؛ vy = ٠\n      ئەگەر ماوسگیراوە() و نەک کێشان و دووری(ماوسX()، ماوسY()، x، y) < ٣٠ { کێشان = ڕاست }\n      ئەگەر کێشان و نەک ماوسگیراوە() {\n        نەگۆڕ d = دووری(ماوسX()، ماوسY()، x، y)\n        نەگۆڕ هێز = بچووکترین(d، ١٢٠) * ٠٫١٥\n        ئەگەر d > ٣ { vx = (x - ماوسX()) / d * هێز؛ vy = (y - ماوسY()) / d * هێز؛ لێدان += ١ }\n        کێشان = هەڵە\n      }\n    }\n    x += vx؛ y += vy\n    vx *= ٠٫٩٨٦؛ vy *= ٠٫٩٨٦\n    ئەگەر x < ٩ { x = ٩؛ vx = -vx }\n    ئەگەر x > ٤٩١ { x = ٤٩١؛ vx = -vx }\n    ئەگەر y < ٩ { y = ٩؛ vy = -vy }\n    ئەگەر y > ٣١١ { y = ٣١١؛ vy = -vy }\n    بۆ هەر ڕ لە ق.ڕێگر {\n      نەگۆڕ نx = سنوور(x، ڕ[٠]، ڕ[٠] + ڕ[٢])\n      نەگۆڕ نy = سنوور(y، ڕ[١]، ڕ[١] + ڕ[٣])\n      ئەگەر دووری(x، y، نx، نy) < ٩ {\n        ئەگەر ڕەها(x - نx) > ڕەها(y - نy) { vx = -vx؛ x += vx * ٢ } ئەگەرنا { vy = -vy؛ y += vy * ٢ }\n      }\n    }\n    ئەگەر دووری(x، y، ق.کون[٠]، ق.کون[١]) < ١٤ و خێرایی < ٥ { تەواو = ڕاست؛ کۆی += لێدان }\n  } ئەگەرنا ئەگەر کلیککراوە() {\n    ئەگەر قۆناغ == قۆناغەکان.درێژی - ١ { قۆناغ = ٠؛ کۆی = ٠ } ئەگەرنا { قۆناغ += ١ }\n    بارکردن(قۆناغ)\n  }\n\n  پاشبنەمابکە(ڕەنگی(٤٠، ١٣٠، ٦٠))\n  ڕەنگبکە(ڕەنگی(٣٥، ١١٥، ٥٠))\n  بۆ i لە ٠ تا ١٢ { لاکێش(i * ٤٠، ٠، ٢٠، ٣٢٠) }\n  ڕەنگبکە(\"ڕەش\")\n  بازنە(ق.کون[٠]، ق.کون[١]، ١٤)\n  ڕەنگبکە(\"سپی\")\n  لاکێش(ق.کون[٠]، ق.کون[١] - ٤٠، ٢، ٤٠)\n  ڕەنگبکە(\"سوور\")\n  سێگۆشە(ق.کون[٠] + ٢، ق.کون[١] - ٤٠، ق.کون[٠] + ٢٢، ق.کون[١] - ٣٤، ق.کون[٠] + ٢، ق.کون[١] - ٢٨)\n  ڕەنگبکە(ڕەنگی(١٣٠، ٩٠، ٥٠))\n  بۆ هەر ڕ لە ق.ڕێگر { لاکێش(ڕ[٠]، ڕ[١]، ڕ[٢]، ڕ[٣]) }\n  ئەگەر کێشان {\n    هێڵڕەنگبکە(ڕەنگی(٢٥٥، ٢٥٥، ٢٥٥، ٠٫٨))\n    ئەستووریبکە(٢)\n    نەگۆڕ d = بچووکترین(دووری(ماوسX()، ماوسY()، x، y)، ١٢٠)\n    نەگۆڕ ئا = دووری(ماوسX()، ماوسY()، x، y) > ٠ ? ١ / دووری(ماوسX()، ماوسY()، x، y) : ٠\n    هێڵ(x، y، x + (x - ماوسX()) * ئا * d، y + (y - ماوسY()) * ئا * d)\n    هێڵ(x، y، x - (x - ماوسX()) * ئا * d * ٠٫٣، y - (y - ماوسY()) * ئا * d * ٠٫٣)\n  }\n  ڕەنگبکە(\"سپی\")\n  بازنە(x، y، ٨)\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"قۆناغ \" + (قۆناغ + ١) + \"   لێدان: \" + لێدان، ١٠، ٢٥، ٢٠)\n  ئەگەر تەواو { نووسین(\"⛳ لە کونەکە! لێدان: \" + لێدان + (قۆناغ == قۆناغەکان.درێژی - ١ ? \"   کۆی: \" + کۆی : \"\") + \" — کلیک\", ٦٠، ٣٠٥، ٢٠) }\n})\n"
