    "code": "// یاری: خێرایی کاردانەوە ⚡ — کاتێک شاشە سەوز بوو، یەکسەر کلیک بکە! زوو کلیک بکەیت (پێش سەوزبوون) دەدۆڕێت\nقەبارە(٤٠٠، ٢٨٠)\nگۆڕاو دۆخ = \"ئامادە\"           // ئامادە، چاوەڕێ، ئێستا، زوو، ئەنجام\nگۆڕاو کات = ٠\nگۆڕاو ئامانج = ٠\nگۆڕاو کاردانەوە = ٠\nگۆڕاو باشترین = ٠\nگۆڕاو هەوڵەکان = []\n\nیاریبکە(() => {\n  کات += ١\n  ئەگەر کلیککراوە() {\n    ئەگەر دۆخ == \"ئامادە\" یان دۆخ == \"ئەنجام\" یان دۆخ == \"زوو\" {\n      دۆخ = \"چاوەڕێ\"؛ کات = ٠؛ ئامانج = هەڕەمەکی( 6٠، ١٨٠)\n    } ئەگەرنا ئەگەر دۆخ == \"چاوەڕێ\" {\n      دۆخ = \"زوو\"\n    } ئەگەرنا ئەگەر دۆخ == \"ئێستا\" {\n      کاردانەوە = خوارکە(کات * ١٦٫٧)\n      هەوڵەکان.زیادبکە(کاردانەوە)\n      ئەگەر باشترین == ٠ یان کاردانەوە < باشترین { باشترین = کاردانەوە }\n      دۆخ = \"ئەنجام\"\n    }\n  }\n  ئەگەر دۆخ == \"چاوەڕێ\" و کات >= ئامانج { دۆخ = \"ئێستا\"؛ کات = ٠ }\n\n  پاشبنەمابکە(دۆخ == \"ئێستا\" ? ڕەنگی(٣٠، ١٨٠، ٨٠) : دۆخ == \"چاوەڕێ\" ? ڕەنگی(٢٠٠، ٥٠، ٥٠) : دۆخ == \"زوو\" ? ڕەنگی(٢٢٠، ١٣٠، ٣٠) : ڕەنگی(٣٠، ٥٠، ١٠٠))\n  ڕەنگبکە(\"سپی\")\n  ئەگەر دۆخ == \"ئامادە\" { نووسین(\"کلیک بکە بۆ دەستپێک\", ٩٠، ١٣٥، ٢٨) }\n  ئەگەر دۆخ == \"چاوەڕێ\" { نووسین(\"چاوەڕێ بکە... (سوور)\", ٨٠، ١٣٥، ٢٨) }\n  ئەگەر دۆخ == \"ئێستا\" { نووسین(\"ئێستا کلیک بکە!\", ٩٠، ١٣٥، ٣٢) }\n  ئەگەر دۆخ == \"زوو\" { نووسین(\"زۆر زوو بوو! کلیک = دووبارە\", ٥٠، ١٣٥، ٢٦) }\n  ئەگەر دۆخ == \"ئەنجام\" {\n    نووسین(کاردانەوە + \" ms\", ١٣٠، ١٢٠، ٤٨)\n    نووسین(\"کلیک = دووبارە\", ١٤٠، ١٧٠، ٢٠)\n  }\n  ڕەنگبکە(ڕەنگی(٢٥٥، ٢٥٥، ٢٥٥، ٠٫٧))\n  ئەگەر باشترین > ٠ { نووسین(\"باشترین: \" + باشترین + \" ms\", ١٠، ٢٦٠، ١٨) }\n  نووسین(\"هەوڵ: \" + هەوڵەکان.درێژی، ٣٢٠، ٢٦٠، ١٨)\n})\n"
