    "id": "77-towers",
    "title": "🎮 پاراستنی قەڵا (یاری)",
    "group": "game",
    "desc": "تاوەر دابنێ و قەڵاکەت بپارێزە.",
    "hint": "کلیک",
    "thumb": 3,
    "code": "// یاری: پاراستنی قەڵا 🏰 — لەسەر زەوی سەوزەکان کلیک بکە بۆ دانانی تاوەر (٥٠ زێڕ). تاوەرەکان دوژمنەکان دەتەقێنن. پێش ئەوەی بگەنە کۆتایی ڕێگا ڕایانبگرە!\nقەبارە(٥٠٠، ٣٤٠)\n// خاڵەکانی ڕێگا (ستوون، ڕیز) — هەر خانەیەک ٥٠ پیکسڵ\nنەگۆڕ ڕێگا = [[٠، ١]، [٨، ١]، [٨، ٣]، [١، ٣]، [١، ٥]، [٩، ٥]]\nگۆڕاو خانەی_ڕێگا = {}\nگۆڕاو تاوەرەکان = []\nگۆڕاو دوژمنەکان = []\nگۆڕاو زێڕ = ١٠٠\nگۆڕاو ژیان = ١٠\nگۆڕاو شەپۆل = ١\nگۆڕاو کات = ٠\nگۆڕاو دروستکراو = ٠\nگۆڕاو خاڵ = ٠\nگۆڕاو تیرەکان = []\n\nکار ناوەند(ج) { گەڕێنەوە { x: ج[٠] * ٥٠ + ٢٥، y: ج[١] * ٥٠ + ٦٥ } }\n\nکار ڕێگاساز() {\n  خانەی_ڕێگا = {}\n  بۆ i لە ٠ تا ڕێگا.درێژی - ٢ {\n    نەگۆڕ a = ڕێگا[i]\n    نەگۆڕ b = ڕێگا[i + ١]\n    نەگۆڕ gx = b[٠] > a[٠] ? ١ : b[٠] < a[٠] ? -١ : ٠\n    نەگۆڕ gy = b[١] > a[١] ? ١ : b[١] < a[١] ? -١ : ٠\n    گۆڕاو cx = a[٠]\n    گۆڕاو cy = a[١]\n    هەتا cx != b[٠] یان cy != b[١] { خانەی_ڕێگا[cx + \",\" + cy] = ڕاست؛ cx += gx؛ cy += gy }\n    خانەی_ڕێگا[b[٠] + \",\" + b[١]] = ڕاست\n  }\n}\nڕێگاساز()\n\nکار دووبارە() { تاوەرەکان = []؛ دوژمنەکان = []؛ زێڕ = ١٠٠؛ ژیان = ١٠؛ شەپۆل = ١؛ کات = ٠؛ دروستکراو = ٠؛ خاڵ = ٠ }\n\nیاریبکە(() => {\n  کات += ١\n  ئەگەر ژیان > ٠ {\n    ئەگەر کلیککراوە() و ماوسY() > ٤٠ {\n      نەگۆڕ c = خوارکە(ماوسX() / ٥٠)\n      نەگۆڕ r = خوارکە((ماوسY() - ٤٠) / ٥٠)\n      نەگۆڕ داگیرکراوە = تاوەرەکان.پاڵاوتن(ت => ت.c == c و ت.r == r).درێژی > ٠\n      ئەگەر نەک خانەی_ڕێگا[c + \",\" + r] و نەک داگیرکراوە و زێڕ >= ٥٠ و c < ١٠ و r < ٦ {\n        تاوەرەکان.زیادبکە({ c: c، r: r، ساردبوونەوە: ٠ })؛ زێڕ -= ٥٠\n      }\n    }\n    // دوژمنی نوێ: هەر شەپۆلێک ١٠ + شەپۆل*٤\n    ئەگەر دروستکراو < ٨ + شەپۆل * ٤ و کات % ٤٠ == ٠ {\n      نەگۆڕ دەستپێک = ناوەند(ڕێگا[٠])\n      دوژمنەکان.زیادبکە({ x: -٢٠، y: دەستپێک.y، ئامانج: ١، ژیانی: ٣ + شەپۆل * ٢، زۆرترین: ٣ + شەپۆل * ٢، خ: ١٫٢ + شەپۆل * ٠٫١ })\n      دروستکراو += ١\n    }\n    بۆ هەر د لە دوژمنەکان {\n      نەگۆڕ ئا = ناوەند(ڕێگا[د.ئامانج])\n      نەگۆڕ دوور = دووری(د.x، د.y، ئا.x، ئا.y)\n      ئەگەر دوور < د.خ + ٠٫٥ {\n        د.x = ئا.x؛ د.y = ئا.y؛ د.ئامانج += ١\n        ئەگەر د.ئامانج >= ڕێگا.درێژی { د.گەیشت = ڕاست؛ ژیان -= ١ }\n      } ئەگەرنا { د.x += (ئا.x - د.x) / دوور * د.خ؛ د.y += (ئا.y - د.y) / دوور * د.خ }\n    }\n    // تاوەرەکان\n    بۆ هەر ت لە تاوەرەکان {\n      ت.ساردبوونەوە -= ١\n      ئەگەر ت.ساردبوونەوە <= ٠ {\n        نەگۆڕ ن = ناوەند([ت.c، ت.r])\n        گۆڕاو ئامانج = هیچ\n        بۆ هەر د لە دوژمنەکان {\n          ئەگەر نەک د.گەیشت و دووری(ن.x، ن.y، د.x، د.y) < ١٢٠ {\n            ئەگەر نەک ئامانج یان د.ئامانج > ئامانج.ئامانج { ئامانج = د }\n          }\n        }\n        ئەگەر ئامانج {\n          ئامانج.ژیانی -= ١\n          ت.ساردبوونەوە = ٢٠\n          تیرەکان.زیادبکە({ a: ن.x، b: ن.y، c: ئامانج.x، d: ئامانج.y، ژیان: ٥ })\n          ئەگەر ئامانج.ژیانی <= ٠ { ئامانج.مردووە = ڕاست؛ زێڕ += ١٠؛ خاڵ += ١٠ }\n        }\n      }\n    }\n    دوژمنەکان = دوژمنەکان.پاڵاوتن(د => نەک د.مردووە و نەک د.گەیشت)\n    ئەگەر دروستکراو >= ٨ + شەپۆل * ٤ و دوژمنەکان.درێژی == ٠ { شەپۆل += ١؛ دروستکراو = ٠؛ زێڕ += ٣٠ }\n  } ئەگەرنا ئەگەر کلیککراوە() { دووبارە() }\n  بۆ هەر ی لە تیرەکان { ی.ژیان -= ١ }\n  تیرەکان = تیرەکان.پاڵاوتن(ی => ی.ژیان > ٠)\n\n  پاشبنەمابکە(ڕەنگی(٣٠، ٧٠، ٤٠))\n  بۆ r لە ٠ تا ٥ {\n    بۆ c لە ٠ تا ٩ {\n      ڕەنگبکە(خانەی_ڕێگا[c + \",\" + r] ? ڕەنگی(١٨٠، ١٥٥، ١١٠) : ڕەنگی(٤٥ + (c + r) % ٢ * ٨، ١٠٥، ٦٠))\n      لاکێش(c * ٥٠ + ١، r * ٥٠ + ٤١، ٤٨، ٤٨)\n    }\n  }\n  بۆ هەر ت لە تاوەرەکان {\n    نەگۆڕ ن = ناوەند([ت.c، ت.r])\n    ڕەنگبکە(ڕەنگی(٨٠، ٨٠، ١٢٠))\n    لاکێش(ن.x - ١٥، ن.y - ١٥، ٣٠، ٣٠)\n    ڕەنگبکە(\"سوور\")\n    بازنە(ن.x، ن.y، ٩)\n    ڕەنگبکە(\"سپی\")\n    بازنە(ن.x، ن.y، ٣)\n  }\n  بۆ هەر د لە دوژمنەکان {\n    ڕەنگبکە(ڕەنگی(٢٢٠، ٦٠، ٦٠))\n    بازنە(د.x، د.y، ١٢)\n    ڕەنگبکە(\"ڕەش\")\n    لاکێش(د.x - ١٢، د.y - ٢٠، ٢٤، ٤)\n    ڕەنگبکە(\"سەوز\")\n    لاکێش(د.x - ١٢، د.y - ٢٠، ٢٤ * د.ژیانی / د.زۆرترین، ٤)\n  }\n  هێڵڕەنگبکە(\"زەرد\")\n  ئەستووریبکە(٢)\n  بۆ هەر ی لە تیرەکان { هێڵ(ی.a، ی.b، ی.c، ی.d) }\n  ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٦))\n  لاکێش(٠، ٠، ٥٠٠، ٤٠)\n  ڕەنگبکە(\"زەرد\")\n  نووسین(\"زێڕ: \" + زێڕ، ١٠، ٢٧، ١٨)\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"شەپۆل \" + شەپۆل، ١٥٠، ٢٧، ١٨)\n  ڕەنگبکە(\"سوور\")\n  نووسین(\"❤ \" + گەورەترین(ژیان، ٠)، ٢٧٠، ٢٧، ١٨)\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"خاڵ: \" + خاڵ، ٣٦٠، ٢٧، ١٨)\n  ئەگەر ژیان <= ٠ {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٦))\n    لاکێش(٠، ٠، ٥٠٠، ٣٤٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(\"قەڵا کەوت! شەپۆل \" + شەپۆل، ١٤٠، ١٦٠، ٣٠)\n    نووسین(\"کلیک = دووبارە\", ٢٠٠، ٢٠٠، ٢٠)\n  }\n})\n"
