    "code": "// یاری: تانکەکان 💥 — ↑ ↓ گۆشە، ← → هێز، بۆشایی = تەقە. تانکی سوور بتەقێنە پێش ئەوەی ئەو تۆ بتەقێنێت! (٣ لێدان)\nقەبارە(٥٠٠، ٣٢٠)\nگۆڕاو زەوی = []\nگۆڕاو تانک = { x: ٦٠، گۆشە: ٤٥، هێز: ٥٠، ژیان: ٣ }\nگۆڕاو دوژمن = { x: ٤٤٠، ژیان: ٣ }\nگۆڕاو گوللە = هیچ\nگۆڕاو نۆرە = \"تۆ\"           // تۆ، دوژمن، تەواو\nگۆڕاو با = ٠\nگۆڕاو چاوەڕێ = ٠\nگۆڕاو پەیام = \"\"\nگۆڕاو پێشوو = هەڵە\n\nکار بەرزی(x) { گەڕێنەوە زەوی[سنوور(خوارکە(x)، ٠، ٤٩٩)] }\n\nکار نەخشە_نوێ() {\n  زەوی = []\n  نەگۆڕ a = هەڕەمەکی(٠، ٣٦٠)\n  بۆ x لە ٠ تا ٤٩٩ { زەوی.زیادبکە(٢١٠ + سینۆس((x + a) / ٦٠) * ٣٠ + سینۆس((x + a * ٢) / ٢٣) * ١٠) }\n  با = هەڕەمەکی(-٥، ٥) / ٣٠\n}\n\nکار دەستپێکردن() { نەخشە_نوێ()؛ تانک.ژیان = ٣؛ دوژمن.ژیان = ٣؛ نۆرە = \"تۆ\"؛ گوللە = هیچ؛ پەیام = \"\" }\nدەستپێکردن()\n\nکار تەقە(لە، گۆشە، هێز، ئاڕاستە) {\n  نەگۆڕ g = گۆشە * پای / ١٨٠\n  گوللە = { x: لە.x، y: بەرزی(لە.x) - ١٥، vx: کۆسینۆس(g) * هێز / ٨ * ئاڕاستە، vy: -سینۆس(g) * هێز / ٨، ئاڕاستە: ئاڕاستە }\n}\n\nکار تەقینەوە(x، y) {\n  بۆ i لە -٢٥ تا ٢٥ { نەگۆڕ ک = سنوور(خوارکە(x) + i، ٠، ٤٩٩)؛ زەوی[ک] += گەورەترین(٠، ٢٠ - ڕەها(i) * ٠٫٨) }\n  ئەگەر دووری(x، y، دوژمن.x، بەرزی(دوژمن.x)) < ٣٥ { دوژمن.ژیان -= ١ }\n  ئەگەر دووری(x، y، تانک.x، بەرزی(تانک.x)) < ٣٥ { تانک.ژیان -= ١ }\n}\n\nیاریبکە(() => {\n  ئەگەر نۆرە == \"تۆ\" و نەک گوللە {\n    ئەگەر کلیل(\"سەرەوە\") { تانک.گۆشە = بچووکترین(٨٥، تانک.گۆشە + ١) }\n    ئەگەر کلیل(\"خوارەوە\") { تانک.گۆشە = گەورەترین(٥، تانک.گۆشە - ١) }\n    ئەگەر کلیل(\"چەپ\") { تانک.هێز = گەورەترین(١٠، تانک.هێز - ١) }\n    ئەگەر کلیل(\"ڕاست\") { تانک.هێز = بچووکترین(١٠٠، تانک.هێز + ١) }\n    ئەگەر کلیل(\"بۆشایی\") و نەک پێشوو { تەقە(تانک، تانک.گۆشە، تانک.هێز، ١) }\n  }\n  پێشوو = کلیل(\"بۆشایی\")\n  ئەگەر نۆرە == \"دوژمن\" و نەک گوللە {\n    چاوەڕێ -= ١\n    ئەگەر چاوەڕێ <= ٠ { تەقە(دوژمن، هەڕەمەکی(٣٠، ٦٠)، هەڕەمەکی(٤٥، ٨٠)، -١) }\n  }\n  ئەگەر گوللە {\n    گوللە.vy += ٠٫٠٨؛ گوللە.vx += با\n    گوللە.x += گوللە.vx؛ گوللە.y += گوللە.vy\n    ئەگەر گوللە.x < ٠ یان گوللە.x > ٥٠٠ یان گوللە.y > بەرزی(گوللە.x) {\n      تەقینەوە(گوللە.x، گوللە.y)\n      نەگۆڕ لە_تۆ = گوللە.ئاڕاستە == ١\n      گوللە = هیچ\n      ئەگەر دوژمن.ژیان <= ٠ { نۆرە = \"تەواو\"؛ پەیام = \"بردتەوە! 🎉\" } ئەگەرنا ئەگەر تانک.ژیان <= ٠ { نۆرە = \"تەواو\"؛ پەیام = \"دۆڕاویت\" } ئەگەرنا {\n        نۆرە = لە_تۆ ? \"دوژمن\" : \"تۆ\"؛ چاوەڕێ = ٦٠\n        با = هەڕەمەکی(-٥، ٥) / ٣٠\n      }\n    }\n  }\n  ئەگەر نۆرە == \"تەواو\" و کلیککراوە() { دەستپێکردن() }\n\n  پاشبنەمابکە(ڕەنگی(١٣٥، ٢٠٦، ٢٣٥))\n  ڕەنگبکە(ڕەنگی(٩٠، ١٤٠، ٧٠))\n  بۆ x لە ٠ تا ٤٩٩ { لاکێش(x، زەوی[x]، ١٫٥، ٣٢٠ - زەوی[x]) }\n  نەگۆڕ ت = [[تانک.x، \"ئاسمانی\"، ١]، [دوژمن.x، \"سوور\"، -١]]\n  بۆ هەر ڕ لە ت {\n    نەگۆڕ y = بەرزی(ڕ[٠])\n    ڕەنگبکە(ڕ[١])\n    لاکێش(ڕ[٠] - ١٨، y - ١٢، ٣٦، ١٢)\n    بازنە(ڕ[٠]، y - ١٢، ٩)\n  }\n  هێڵڕەنگبکە(\"ڕەش\")\n  ئەستووریبکە(٥)\n  نەگۆڕ gg = تانک.گۆشە * پای / ١٨٠\n  هێڵ(تانک.x، بەرزی(تانک.x) - ١٨، تانک.x + کۆسینۆس(gg) * ٢٠، بەرزی(تانک.x) - ١٨ - سینۆس(gg) * ٢٠)\n  هێڵ(دوژمن.x، بەرزی(دوژمن.x) - ١٨، دوژمن.x - ٢٠، بەرزی(دوژمن.x) - ٢٥)\n  ئەگەر گوللە { ڕەنگبکە(\"ڕەش\")؛ بازنە(گوللە.x، گوللە.y، ٤) }\n  ڕەنگبکە(\"سپی\")\n  نووسین(\"گۆشە: \" + تانک.گۆشە + \"°   هێز: \" + تانک.هێز، ١٠، ٢٥، ١٨)\n  نووسین(\"ژیانی تۆ: \" + تانک.ژیان + \"   دوژمن: \" + دوژمن.ژیان، ٣٠٠، ٢٥، ١٨)\n  نووسین(\"با: \" + (با > ٠ ? \"→\" : \"←\") + گردبکە(ڕەها(با) * ٣٠٠)، ٢١٠، ٥٠، ١٦)\n  ئەگەر نۆرە == \"دوژمن\" و نەک گوللە { نووسین(\"دوژمن ئامانج دەگرێت...\", ١٨٠، ٨٠، ٢٠) }\n  ئەگەر نۆرە == \"تەواو\" { نووسین(پەیام + \" — کلیک = دووبارە\", ١٢٠، ١٢٠، ٢٦) }\n})\n"
