    "id": "93-hockey",
    "title": "🎮 هۆکی ئاسمانی (یاری)",
    "group": "game",
    "desc": "هۆکی ئاسمانی دژی کۆمپیوتەر.",
    "hint": "ماوس",
    "thumb": 30,
    "code": "// یاری: هۆکی ئاسمانی 🏒 — ماوس پاددەکەتە (بەشی خوارەوە). تۆپ بخەرە ناو دەرگای سەرەوەی دوژمن! یەکەم بە ٧ خاڵ دەبات\nقەبارە(٣٠٠، ٤٥٠)\nگۆڕاو پک = { x: ١٥٠، y: ٢٢٥، vx: ٣، vy: ٤ }\nگۆڕاو پاد = { x: ١٥٠، y: ٣٨٠، vx: ٠، vy: ٠ }\nگۆڕاو دژ = { x: ١٥٠، y: ٧٠، vx: ٠، vy: ٠ }\nگۆڕاو خاڵی_تۆ = ٠\nگۆڕاو خاڵی_دژ = ٠\n\nکار دووبارە_پک(ئا) { پک = { x: ١٥٠، y: ٢٢٥، vx: هەڕەمەکی(-٣، ٣)، vy: ئا * ٣ } }\n\nکار پێکدادان(پ) {\n  نەگۆڕ d = دووری(پک.x، پک.y، پ.x، پ.y)\n  ئەگەر d < ٣٥ و d > ٠ {\n    نەگۆڕ nx = (پک.x - پ.x) / d\n    نەگۆڕ ny = (پک.y - پ.y) / d\n    نەگۆڕ خێرایی = بچووکترین(١٣، گەورەترین(٥، دووری(٠، ٠، پک.vx، پک.vy) * ٠٫٧ + دووری(٠، ٠، پ.vx، پ.vy) * ٠٫٨))\n    پک.vx = nx * خێرایی؛ پک.vy = ny * خێرایی\n    پک.x = پ.x + nx * ٣٦؛ پک.y = پ.y + ny * ٣٦\n  }\n}\n\nیاریبکە(() => {\n  ئەگەر خاڵی_تۆ < ٧ و خاڵی_دژ < ٧ {\n    ئەگەر ماوسX() >= ٠ {\n      نەگۆڕ نx = سنوور(ماوسX()، ٢٥، ٢٧٥)\n      نەگۆڕ نy = سنوور(ماوسY()، ٢٥٥، ٤٢٠)\n      پاد.vx = نx - پاد.x؛ پاد.vy = نy - پاد.y\n      پاد.x = نx؛ پاد.y = نy\n    }\n    // کۆمپیوتەر: خێرایی سنووردار\n    نەگۆڕ ئامانجx = پک.y < ٢٢٥ ? پک.x : ١٥٠\n    نەگۆڕ ئامانجy = پک.y < ٢٢٥ ? سنوور(پک.y - ٣٠، ٢٥، ١٨٠) : ٧٠\n    دژ.vx = سنوور(ئامانجx - دژ.x، -٤٫٥، ٤٫٥)؛ دژ.vy = سنوور(ئامانجy - دژ.y، -٣، ٣)\n    دژ.x += دژ.vx؛ دژ.y += دژ.vy\n    دژ.x = سنوور(دژ.x، ٢٥، ٢٧٥)\n\n    پک.x += پک.vx؛ پک.y += پک.vy\n    پک.vx *= ٠٫٩٩٥؛ پک.vy *= ٠٫٩٩٥\n    ئەگەر پک.x < ١٢ یان پک.x > ٢٨٨ { پک.vx = -پک.vx؛ پک.x = سنوور(پک.x، ١٢، ٢٨٨) }\n    ئەگەر پک.y < ١٢ و (پک.x < ١٠٠ یان پک.x > ٢٠٠) { پک.vy = -پک.vy؛ پک.y = ١٢ }\n    ئەگەر پک.y > ٤٣٨ و (پک.x < ١٠٠ یان پک.x > ٢٠٠) { پک.vy = -پک.vy؛ پک.y = ٤٣٨ }\n    پێکدادان(پاد)؛ پێکدادان(دژ)\n    ئەگەر پک.y < -١٠ { خاڵی_تۆ += ١؛ دووبارە_پک(١) }\n    ئەگەر پک.y > ٤٦٠ { خاڵی_دژ += ١؛ دووبارە_پک(-١) }\n  } ئەگەرنا ئەگەر کلیککراوە() { خاڵی_تۆ = ٠؛ خاڵی_دژ = ٠؛ دووبارە_پک(١) }\n\n  پاشبنەمابکە(ڕەنگی(١٥، ٣٠، ٥٥))\n  ڕەنگبکە(ڕەنگی(٣٠، ٥٥، ٩٠))\n  لاکێش(٠، ٢٢٢، ٣٠٠، ٦)\n  هێڵڕەنگبکە(ڕەنگی(٣٠، ٥٥، ٩٠))\n  ئەستووریبکە(٤)\n  بازنەهێڵ(١٥٠، ٢٢٥، ٤٠)\n  ڕەنگبکە(ڕەنگی(٢٠٠، ٦٠، ٦٠))\n  لاکێش(١٠٠، ٠، ١٠٠، ٥)؛ لاکێش(١٠٠، ٤٤٥، ١٠٠، ٥)\n  ڕەنگبکە(\"ئاسمانی\")\n  بازنە(پاد.x، پاد.y، ٢٥)\n  ڕەنگبکە(ڕەنگی(١٥، ٣٠، ٥٥))\n  بازنە(پاد.x، پاد.y، ١٢)\n  ڕەنگبکە(\"نارنجی\")\n  بازنە(دژ.x، دژ.y، ٢٥)\n  ڕەنگبکە(ڕەنگی(١٥، ٣٠، ٥٥))\n  بازنە(دژ.x، دژ.y، ١٢)\n  ڕەنگبکە(\"سپی\")\n  بازنە(پک.x، پک.y، ١٠)\n  ڕەنگبکە(ڕەنگی(٢٥٥، ٢٥٥، ٢٥٥، ٠٫٥))\n  نووسین(خاڵی_دژ، ١٠، ٢١٠، ٢٦)\n  نووسین(خاڵی_تۆ، ١٠، ٢٥٤، ٢٦)\n  ئەگەر خاڵی_تۆ >= ٧ یان خاڵی_دژ >= ٧ {\n    ڕەنگبکە(ڕەنگی(٠، ٠، ٠، ٠٫٧))\n    لاکێش(٠، ٠، ٣٠٠، ٤٥٠)\n    ڕەنگبکە(\"سپی\")\n    نووسین(خاڵی_تۆ >= ٧ ? \"بردتەوە! 🎉\" : \"کۆمپیوتەر بردیەوە\", ٨٠، ٢٠٠، ٢٨)\n    نووسین(\"کلیک = دووبارە\", ٩٥، ٢٤٠، ٢٠)\n  }\n})\n"
